class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        result = []
        for i, row in enumerate(grid):
            if i % 2 == 0:  # even row: left to right
                order = row
            else:  # odd row: right to left
                order = row[::-1]
            # take every alternate cell starting from first
            for j, val in enumerate(order):
                if j % 2 == 0:
                    result.append(val)
        return result
