from typing import List

class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)
        from functools import lru_cache

        @lru_cache(None)
        def dfs(i: int) -> int:
            # if fewer than 3 remain
            if i >= n:
                return 0
            if i + 2 >= n:
                return max(nums[i:])

            # choose any pair among i, i+1, i+2
            best = float('inf')
            indices = [i, i+1, i+2]
            for a in range(3):
                for b in range(a+1, 3):
                    remaining = indices[3 - a - b]  # the one not removed
                    cost = max(nums[indices[a]], nums[indices[b]]) + dfs(remaining)
                    if cost < best:
                        best = cost
            return best

        return dfs(0)
