def solve() -> None:
    it = iter(sys.stdin.read().strip().split())
    try:
        n = int(next(it))
    except StopIteration:
        return
    A = [int(next(it)) for _ in range(n)]
    B = [int(next(it)) for _ in range(n)]

    knownA = [a for a in A if a != -1]
    knownB = [b for b in B if b != -1]

    # Determine fixed S if any pair of known values exists
    fixed_S = None
    for a in knownA:
        for b in knownB:
            s = a + b
            if fixed_S is None:
                fixed_S = s
            elif fixed_S != s:
                print("No")
                return

    # Count frequencies
    cntA = Counter(knownA)
    cntB = Counter(knownB)

    # Function to check feasibility for a given S
    def check(S: int) -> bool:
        # For known A values
        for a, ca in cntA.items():
            if cntB.get(S - a, 0) < ca:
                return False
        # For known B values
        for b, cb in cntB.items():
            if cntA.get(S - b, 0) < cb:
                return False
        return True

    if fixed_S is not None:
        # Need also S >= max known value to keep other side non-negative
        if fixed_S < max(knownA + knownB, default=0):
            print("No")
            return
        print("Yes" if check(fixed_S) else "No")
        return

    # No fixed S: find candidates
    # S must be in intersection of {a + b | a in knownA, b in knownB}
    if not knownA or not knownB:
        # all elements are -1, we can choose any S >= 0
        print("Yes")
        return

    # Compute all possible sums
    sum_set = set()
    for a in knownA:
        for b in knownB:
            sum_set.add(a + b)

    # Additionally ensure S >= max_known to keep other side non-negative
    max_known = max(knownA + knownB)

    for S in sum_set:
        if S < max_known:
            continue
        if check(S):
            print("Yes")
            return
    print("No")

if __name__ == "__main__":
    solve()
