        n = len(nums)
        count = [0] * 51  # nums[i] <= 50
        for i, val in enumerate(nums):
            start = max(0, i - k + 1)
            end = min(i, n - k)
            count[val] += end - start + 1
        res = -1
        for val in range(51):
            if count[val] == 1 and val > res:
                res = val
