from typing import List
class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        import sys
        sys.setrecursionlimit(10000)
        odds = (n + 1) // 2
        evens = n // 2
        LIMIT = 10**15 + 1

        from functools import lru_cache

        @lru_cache(None)
        def dp(o, e, last):
            # last: 0 even, 1 odd, 2 none (start)
            if o == 0 and e == 0:
                return 1
            total = 0
            if last == 2:
                # can pick either parity
                if o > 0:
                    total += dp(o-1, e, 1)
                if e > 0:
                    total += dp(o, e-1, 0)
            else:
                # must pick opposite parity
                if last == 1:  # last odd, need even
                    if e > 0:
                        total += dp(o, e-1, 0)
                else:  # last even, need odd
                    if o > 0:
                        total += dp(o-1, e, 1)
            return min(total, LIMIT)

        total_perm = dp(odds, evens, 2)
        if k > total_perm:
            return []

        odds_list = [i for i in range(1, n+1) if i % 2 == 1]
        evens_list = [i for i in range(1, n+1) if i % 2 == 0]
        res = []
        last_parity = 2
        for pos in range(n):
            for x in sorted(odds_list if (last_parity==2 or last_parity==0) else evens_list if (last_parity==2 or last_parity==1) else []):
                pass
            # We need iterate over all remaining numbers sorted
            remaining = sorted(odds_list + evens_list)
            for x in remaining:
                p = x % 2
                if last_parity != 2:
                    if last_parity == p:
                        continue
                o_rem = odds
                e_rem = evens
                if p == 1:
                    o_rem -= 1
                else:
                    e_rem -= 1
                cnt = dp(o_rem, e_rem, p)
                if k > cnt:
                    k -= cnt
                else:
                    res.append(x)
                    if p == 1:
                        odds_list.remove(x)
                        odds -= 1
                    else:
                        evens_list.remove(x)
                        evens -= 1
                    last_parity = p
                    break
        return res
