class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        m = n // 2
        INF = 10**18
        dp_prev = [0, 0, 0]  # cost up to previous pair, ending with prev_color

        for k in range(m):
            i, j = k, n - 1 - k
            dp_curr = [INF, INF, INF]
            for pc in range(3):  # previous house color
                base = dp_prev[pc]
                if base >= INF:
                    continue
                for c1 in range(3):  # color for house i
                    if c1 == pc:
                        continue
                    for c2 in range(3):  # color for house j
                        if c2 == c1:
                            continue
                        new_cost = base + cost[i][c1] + cost[j][c2]
                        if new_cost < dp_curr[c2]:
                            dp_curr[c2] = new_cost
            dp_prev = dp_curr

        return min(dp_prev)
