class Solution:
    def minCost(self, n: int, cost: list[list[int]]) -> int:
        mid = n // 2
        dp = {(-1, -1): 0}
        for i in range(mid):
            j = n - 1 - i
            new_dp = {}
            for (cl_prev, cr_prev), cur_cost in dp.items():
                for cl in range(3):
                    if cl == cl_prev:
                        continue
                    for cr in range(3):
                        if cr == cr_prev or cl == cr:
                            continue
                        nc = cur_cost + cost[i][cl] + cost[j][cr]
                        key = (cl, cr)
                        if key not in new_dp or nc < new_dp[key]:
                            new_dp[key] = nc
            dp = new_dp
        return min(dp.values())
