class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        import heapq
        n = len(nums)
        # sliding window median
        left = []  # max-heap (store negatives)
        right = []  # min-heap
        lazy_left = {}
        lazy_right = {}
        sum_left = 0
        sum_right = 0
        def prune(heap, lazy):
            while heap and lazy.get(heap[0],0):
                val = heap[0]
                lazy[val]-=1
                if lazy[val]==0:
                    del lazy[val]
                heapq.heappop(heap)
        def rebalance():
            nonlocal sum_left, sum_right
            if len(left) > len(right)+1:
                val = -heapq.heappop(left)
                prune(left,lazy_left)
                heapq.heappush(right,val)
                sum_left -= val
                sum_right += val
            elif len(right) > len(left):
                val = heapq.heappop(right)
                prune(right,lazy_right)
                heapq.heappush(left,-val)
                sum_right -= val
                sum_left += val
        def add(val):
            nonlocal sum_left, sum_right
            if not left or val <= -left[0]:
                heapq.heappush(left,-val)
                sum_left += val
            else:
                heapq.heappush(right,val)
                sum_right += val
            rebalance()
        def remove(val):
            nonlocal sum_left, sum_right
            if val <= -left[0]:
                sum_left -= val
                lazy_left[-val] = lazy_left.get(-val,0)+1
                if -left[0]==-val:
                    prune(left,lazy_left)
            else:
                sum_right -= val
                lazy_right[val] = lazy_right.get(val,0)+1
                if right[0]==val:
                    prune(right,lazy_right)
            rebalance()
        costs = [0]*(n-x+1)
        # init window
        for i in range(x):
            add(nums[i])
        median = -left[0]
        costs[0] = median*len(left)-sum_left + sum_right-median*len(right)
        for i in range(1,n-x+1):
            remove(nums[i-1])
            add(nums[i+x-1])
            median = -left[0]
            costs[i] = median*len(left)-sum_left + sum_right-median*len(right)
        INF = 10**18
        prev = [INF]*(n)
        cur = [INF]*(n)
        for t in range(1,k+1):
            best = INF
            idx = -1
            for i in range(n-x+1):
                if i - x >= 0:
                    val = prev[i-x]
                    if val < best:
                        best = val
                # also consider starting at i when t==1
                if t==1:
                    best = 0
                cur[i] = best + costs[i]
            prev,cur = cur,[INF]*n
        return prev[n-x] if k==1 else min(prev[n-x+1:])
