        n=len(nums)
        prefN=[0]*(n+1)
        prefC=[0]*(n+1)
        for i in range(1,n+1):
            prefN[i]=prefN[i-1]+nums[i-1]
            prefC[i]=prefC[i-1]+cost[i-1]
        INF=10**18
        dp=[[INF]*(n+1) for _ in range(n+1)]
        dp[0][0]=0
        hulls=[None]*(n+1)
        for j in range(n+1):
            hulls[j]=LiChao(-2000000,0)
        for j in range(1,n+1):
            hulls[j-1].add_line(0,dp[0][j-1])
        for i in range(1,n+1):
            for j in range(1,i+1):
                C=prefN[i]+k*j
                val=hulls[j-1].query(-C)+C*prefC[i]
                dp[i][j]=val
                hulls[j].add_line(prefC[i],val)
        return min(dp[n][1:n+1])
