from functools import lru_cache
from typing import List, Tuple

class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        prefN = [0]*(n+1)
        prefC = [0]*(n+1)
        for i in range(n):
            prefN[i+1] = prefN[i] + nums[i]
            prefC[i+1] = prefC[i] + cost[i]

        @lru_cache(None)
        def dfs(i: int) -> Tuple[int, int]:
            """Return (min_cost, segments_used) for first i elements."""
            if i == 0:
                return (0, 0)
            best_cost = None
            best_seg = None
            for j in range(i):
                prev_cost, prev_seg = dfs(j)
                seg = prev_seg + 1
                sumN = prefN[i] - prefN[j]
                sumC = prefC[i] - prefC[j]
                cur = (sumN + k*seg) * sumC
                total = prev_cost + cur
                if best_cost is None or total < best_cost:
                    best_cost = total
                    best_seg = seg
            return (best_cost, best_seg)

        return dfs(n)[0]
