class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        prefix = [0]*(n+1)
        for i,x in enumerate(nums):
            prefix[i+1] = prefix[i]+x
        NEG = -10**15
        dp = [[NEG]*(k+1) for _ in range(n)]
        for i in range(n):
            dp[i][0] = 0
        for i in range(n):
            for j in range(1, k+1):
                # carry over previous best
                if i>0:
                    dp[i][j] = max(dp[i][j], dp[i-1][j])
                # try ending subarray at i with length len
                for l in range(m, min(3, i+1)+1):
                    start = i-l
                    cur = prefix[i+1]-prefix[start+1]
                    prev = dp[start][j-1] if start>=0 else (0 if j-1==0 else NEG)
                    if prev != NEG:
                        dp[i][j] = max(dp[i][j], prev+cur)
        return dp[n-1][k]
