import sys

def count_le(N):
    if N < 10:
        return 0
    digits = list(map(int, str(N)))
    n = len(digits)
    total = 0
    # lengths shorter than n
    for length in range(2, n):
        for d in range(1, 10):
            total += pow(d, length - 1)
    # length equal to n
    for d in range(1, 10):
        if d > digits[0]:
            continue
        if d < digits[0]:
            total += pow(d, n - 1)
            continue
        # d == digits[0]
        tight = True
        for pos in range(1, n):
            if not tight:
                break
            limit = digits[pos]
            rem = n - pos - 1
            # digits less than limit
            max_digit = min(d - 1, limit - 1)
            if max_digit >= 0:
                total += (max_digit + 1) * pow(d, rem)
            # choose digit equal to limit if possible
            if limit < d:
                total += pow(d, rem)
                break
            if limit >= d:
                break
    return total

def solve():
