import sys

def count_upto(x: int) -> int:
    if x < 10:
        return 0
    s = str(x)
    n = len(s)
    # precompute powers up to 18
    pow_d = [[0] * (n) for _ in range(10)]
    for d in range(1, 10):
        pow_d[d][0] = 1
        for k in range(1, n):
            pow_d[d][k] = pow_d[d][k-1] * d

    res = 0
    # lengths shorter than n
    for l in range(2, n):
        for d in range(1, 10):
            res += pow_d[d][l-1]
    fd = int(s[0])
    # leading digit less than fd
    for d in range(1, fd):
        res += pow_d[d][n-1]
    # leading digit equal to fd
    for i in range(1, n):
        cur = int(s[i])
        limit = min(cur, fd-1)
        for t in range(limit + 1):
            if t < cur:
                res += pow_d[fd][n-1-i]
        if cur >= fd:
            continue
        else:
            break
    else:
        # all digits processed
        res += 1
    return res

