import sys

def count_snake(n: int) -> int:
    if n < 10:
        return 0
    s = str(n)
    L = len(s)
    total = 0
    # lengths less than L
    for l in range(1, L):
        for d in range(1, 10):
            total += pow(d, l - 1)
    # length L
    leading = int(s[0])
    # first digit choices less than leading
    for d in range(1, leading):
        total += pow(d, L - 1)
    # process subsequent digits
    for i in range(1, L):
        cur = int(s[i])
        remaining = L - i - 1
        for d in range(0, cur):
            if leading > d:
                total += pow(leading, remaining)
        leading = leading  # leading stays same
    # check if n itself is snake
    if all(int(ch) < int(s[0]) for ch in s[1:]):
        total += 1
    return total

def main():
