import sys
import bisect

def solve() -> None:
    it = iter(sys.stdin.read().strip().split())
    N = int(next(it)); Q = int(next(it))
    A = [int(next(it)) for _ in range(N)]
    queries = []
    for _ in range(Q):
        R = int(next(it)); X = int(next(it))
        queries.append((R, X, _))
    # coordinate compression
    vals = set(A)
    for _, X, _ in queries:
        vals.add(X)
    comp = {v: i+1 for i, v in enumerate(sorted(vals))}
    size = len(comp) + 2

    class BIT:
        def __init__(self, n):
            self.n = n
            self.t = [0]*(n+1)
        def update(self, i, v):
            while i <= self.n:
                if v > self.t[i]:
                    self.t[i] = v
                i += i & -i
        def query(self, i):
            res = 0
            while i > 0:
                if self.t[i] > res:
                    res = self.t[i]
                i -= i & -i
            return res

    bit = BIT(size)
    # sort queries by R
    queries.sort()
    ans = [0]*Q
    cur = 0
    for R, X, idx in queries:
        while cur < R:
            val = A[cur]
            ci = comp[val]
            best = bit.query(ci-1) + 1
            bit.update(ci, best)
            cur += 1
        ans[idx] = bit.query(comp[X])
    sys.stdout.write("\n".join(map(str, ans)))

if __name__ == "__main__":
    solve()
```

