from typing import List

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n

        # Trie node structure: children dict, count, depth
        class Node:
            __slots__ = ("children", "cnt", "depth")
            def __init__(self, depth=0):
                self.children = {}
                self.cnt = 0
                self.depth = depth

        root = Node()

        # Build trie and count occurrences
        for w in words:
            node = root
            for ch in w:
                if ch not in node.children:
                    node.children[ch] = Node(node.depth + 1)
                node = node.children[ch]
                node.cnt += 1

        ans = [0] * n
        # For each word, find deepest node on its path with cnt > k
        for idx, w in enumerate(words):
            node = root
            best = 0
            for ch in w:
                node = node.children[ch]
                if node.cnt > k:
                    best = node.depth
            ans[idx] = best

        return ans
