from typing import List
import math

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        # Map each element value to its smallest index
        value_to_index = {}
        for idx, val in enumerate(elements):
            if val not in value_to_index or idx < value_to_index[val]:
                value_to_index[val] = idx

        res = [-1] * len(groups)
        for i, g in enumerate(groups):
            best_idx = None
            limit = int(math.isqrt(g))
            for d in range(1, limit + 1):
                if g % d == 0:
                    # Check divisor d
                    if d in value_to_index:
                        idx = value_to_index[d]
                        if best_idx is None or idx < best_idx:
                            best_idx = idx
                    # Check paired divisor g//d
                    other = g // d
                    if other != d and other in value_to_index:
                        idx = value_to_index[other]
                        if best_idx is None or idx < best_idx:
                            best_idx = idx
            if best_idx is not None:
                res[i] = best_idx
        return res
