from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # Prepare events with ordering: OFFLINE before MESSAGE at same timestamp
        prepared = []
        for e in events:
            typ, ts_str, third = e
            ts = int(ts_str)
            order = 0 if typ == "OFFLINE" else 1
            prepared.append((ts, order, typ, third))
        prepared.sort()  # sort by timestamp, then order

        # Track offline status with expiration times
        offline_until = [0] * numberOfUsers  # 0 means online
        mentions = [0] * numberOfUsers

        for ts, _, typ, third in prepared:
            # Update online status for any user whose offline period ended before ts
            for uid in range(numberOfUsers):
                if offline_until[uid] > 0 and offline_until[uid] <= ts:
                    offline_until[uid] = 0

            if typ == "OFFLINE":
                uid = int(third)
                offline_until[uid] = ts + 60
            else:  # MESSAGE
                tokens = third.split()
                if tokens[0] == "ALL":
                    for uid in range(numberOfUsers):
                        mentions[uid] += 1
                elif tokens[0] == "HERE":
                    for uid in range(numberOfUsers):
                        if offline_until[uid] == 0:
                            mentions[uid] += 1
                else:
                    for token in tokens:
                        if token.startswith("id"):
                            uid = int(token[2:])
                            mentions[uid] += 1

        return mentions
