from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        online = set(range(numberOfUsers))
        expiry = {}  # user -> time when online
        current_time = 0

        def process_expiries(up_to):
            nonlocal online
            to_remove = [u for u, t in expiry.items() if t <= up_to]
            for u in to_remove:
                online.add(u)
                del expiry[u]

        for ev in events:
            typ, ts_str, val = ev
            ts = int(ts_str)
            # Process expiries up to current timestamp
            process_expiries(ts)
            current_time = ts

            if typ == "OFFLINE":
                uid = int(val)
                # user guaranteed online
                online.remove(uid)
                expiry[uid] = ts + 60
            else:  # MESSAGE
                if val == "ALL":
                    for uid in range(numberOfUsers):
                        mentions[uid] += 1
                elif val == "HERE":
                    for uid in online:
                        mentions[uid] += 1
                else:
                    tokens = val.split()
                    for token in tokens:
                        if token.startswith("id"):
                            uid = int(token[2:])
                            mentions[uid] += 1
        return mentions
