from typing import List
import heapq

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # Prepare events with priority: OFFLINE before MESSAGE when timestamps equal
        processed = []
        for ev in events:
            t = int(ev[1])
            priority = 0 if ev[0] == "OFFLINE" else 1
            processed.append((t, priority, ev))
        processed.sort()  # sorts by timestamp then priority

        online = set(range(numberOfUsers))
        # heap of (restore_time, user_id)
        restore_heap = []

        mentions = [0] * numberOfUsers

        for t, _, ev in processed:
            # Restore users whose offline period ended
            while restore_heap and restore_heap[0][0] <= t:
                _, uid = heapq.heappop(restore_heap)
                online.add(uid)

            if ev[0] == "OFFLINE":
                uid = int(ev[2])
                # user goes offline immediately
                online.remove(uid)
                heapq.heappush(restore_heap, (t + 60, uid))
            else:  # MESSAGE
                msg = ev[2]
                if msg == "ALL":
                    for uid in range(numberOfUsers):
                        mentions[uid] += 1
                elif msg == "HERE":
                    for uid in online:
                        mentions[uid] += 1
                else:
                    tokens = msg.split()
                    for tok in tokens:
                        if tok.startswith("id"):
                            uid = int(tok[2:])
                            mentions[uid] += 1

        return mentions
