class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        i = 0
        while i < n:
            # find run of identical characters
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            run_len = j - i
            if run_len >= k:
                for start in range(i, j - k + 1):
                    before_ok = (start == 0) or (s[start - 1] != s[start])
                    after_ok = (start + k == n) or (s[start + k] != s[start])
                    if before_ok and after_ok:
                        return True
            i = j
        return False
