import sys
sys.setrecursionlimit(1 << 25)
MOD = 998244353

def solve() -> None:
    N, M = map(int, sys.stdin.readline().split())
    A = list(map(int, sys.stdin.readline().split()))
    g = [[] for _ in range(N)]
    rg = [[] for _ in range(N)]
    for i, a in enumerate(A):
        g[i].append(a-1)
        rg[a-1].append(i)

    # Kosaraju to find SCCs
    visited = [False]*N
    order = []
    def dfs(v):
        visited[v] = True
        for to in g[v]:
            if not visited[to]:
                dfs(to)
        order.append(v)
    for v in range(N):
        if not visited[v]:
            dfs(v)

    comp = [-1]*N
    def rdfs(v, cid):
        comp[v] = cid
        for to in rg[v]:
            if comp[to] == -1:
                rdfs(to, cid)
    cid = 0
    for v in reversed(order):
        if comp[v] == -1:
            rdfs(v, cid)
            cid += 1
    C = cid

    # Build condensation graph
    csize = [0]*C
    cchildren = [[] for _ in range(C)]
    indeg = [0]*C
    for v in range(N):
        csize[comp[v]] += 1
        for to in g[v]:
            if comp[v] != comp[to]:
                cchildren[comp[v]].append(comp[to])
    # Remove duplicates
    for i in range(C):
        cchildren[i] = list(set(cchildren[i]))
    indeg = [0]*C
    for i in range(C):
        for to in cchildren[i]:
            indeg[to] += 1

    # Topological order
    from collections import deque
    q = deque([i for i in range(C) if indeg[i]==0])
    topo = []
    while q:
        v = q.popleft()
        topo.append(v)
        for to in cchildren[v]:
            indeg[to]-=1
            if indeg[to]==0:
                q.append(to)

    # DP
    dp = [None]*C
    for v in reversed(topo):
        if not cchildren[v]:  # leaf
            arr = [0]*(M+1)
            for val in range(1, M+1):
                arr[val] = pow(val, csize[v], MOD)
            dp[v] = arr
        else:
            # compute prod_child[k]
            prod = [1]*(M+1)
            for child in cchildren[v]:
                child_dp = dp[child]
                for k in range(1, M+1):
                    prod[k] = prod[k] * child_dp[k] % MOD
            pref = [0]*(M+1)
            s = 0
            for k in range(1, M+1):
                s = (s + prod[k]) % MOD
                pref[k] = s
            dp[v] = pref

    # Find root SCCs
    roots = [i for i in range(C) if indeg[i]==0]
    # compute answer
    ans = 0
    for val in range(1, M+1):
        prod = 1
        for r in roots:
            prod = prod * dp[r][val] % MOD
        ans = (ans + prod) % MOD
    print(ans)

if __name__ == "__main__":
    solve()
```

