from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # dp_even[sum] = max product for subsequence ending with even length (next add will be odd)
        # dp_odd[sum]  = max product for subsequence ending with odd length (next add will be even)
        dp_even = {}
        dp_odd = {}
        best = -1

        for num in nums:
            # start new subsequence with this num
            if num <= limit:
                s = num
                prod = num
                if s == k:
                    best = max(best, prod)
                if s not in dp_even or prod > dp_even[s]:
                    dp_even[s] = prod

            # extend existing subsequences
            # from even parity: next add will be odd, subtract num
            new_even = {}
            for s, prod in dp_even.items():
                # add num as odd
                ns = s - num
                nprod = prod * num
                if nprod <= limit:
                    if ns == k:
                        best = max(best, nprod)
                    if ns not in new_even or nprod > new_even[ns]:
                        new_even[ns] = nprod
            # from odd parity: next add will be even, add num
            new_odd = {}
            for s, prod in dp_odd.items():
                ns = s + num
                nprod = prod * num
                if nprod <= limit:
                    if ns == k:
                        best = max(best, nprod)
                    if ns not in new_odd or nprod > new_odd[ns]:
                        new_odd[ns] = nprod

            # merge new states
            for ns, nprod in new_even.items():
                if ns not in dp_even or nprod > dp_even[ns]:
                    dp_even[ns] = nprod
            for ns, nprod in new_odd.items():
                if ns not in dp_odd or nprod > dp_odd[ns]:
                    dp_odd[ns] = nprod

        return best
