class Solution:
    def maxProduct(self, nums, k, limit):
        from collections import defaultdict
        dp = [defaultdict(lambda: -1), defaultdict(lambda: -1)]  # parity 0: next index even, 1: odd
        best = -1
        for num in nums:
            if num == 0:
                prod = 0
                if prod <= limit:
                    if k == 0:
                        best = max(best, prod)
                # start new subsequence
                dp[1][num] = max(dp[1].get(num, -1), num if num <= limit else -1)
                continue
            new_dp0, new_dp1 = defaultdict(lambda: -1), defaultdict(lambda: -1)
            # start new subsequence with num
            prod = num
            if prod <= limit:
                if k == prod:
                    best = max(best, prod)
                new_dp1[prod] = max(new_dp1.get(prod, -1), prod)
            # extend existing subsequences
            for parity in (0,1):
                for s, p in dp[parity].items():
                    if p == -1: continue
                    new_parity = 1 - parity
                    new_sum = s + num if new_parity == 1 else s - num
                    new_prod = p * num
                    if new_prod > limit: continue
                    if new_sum == k:
                        best = max(best, new_prod)
                    if new_parity == 0:
                        new_dp0[new_sum] = max(new_dp0.get(new_sum, -1), new_prod)
                    else:
                        new_dp1[new_sum] = max(new_dp1.get(new_sum, -1), new_prod)
            dp[0] = new_dp0
            dp[1] = new_dp1
        return best
