        # dp[(sum, parity, empty)] = max product
        dp = {(0, 0, True): 1}
        for val in nums:
            new_dp = dict(dp)  # copy current states
            for (s, p, empty), prod in dp.items():
                # take current element
                ns = s + (val if p == 0 else -val)
                np = 1 - p
                nprod = prod * val
                if nprod <= limit:
                    key = (ns, np, False)
                    if key not in new_dp or nprod > new_dp[key]:
                        new_dp[key] = nprod
            dp = new_dp

        best = -1
        for (s, p, empty), prod in dp.items():
            if not empty and s == k:
                if prod <= limit and prod > best:
                    best = prod
        return best
