class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        from collections import defaultdict

        # dp[sum][parity] = max product achieving this sum with next index parity
        dp = defaultdict(lambda: [-1, -1])  # parity 0: next index even, 1: odd
        # empty subsequence is not recorded

        best = -1

        for x in nums:
            # consider starting new subsequence with x
            if x <= limit:
                if x == k:
                    best = max(best, x)
                dp[x][0] = max(dp[x][0], x)  # next index will be odd after taking one element

            # copy current dp to avoid in-place updates during iteration
            cur_items = list(dp.items())
            for s, par_vals in cur_items:
                for parity in (0, 1):
                    prod = par_vals[parity]
                    if prod == -1:
                        continue
                    # take x
                    new_parity = 1 - parity
                    new_sum = s + x if parity == 0 else s - x
                    new_prod = prod * x
                    if new_prod > limit:
                        continue
                    if new_prod > dp[new_sum][new_parity]:
                        dp[new_sum][new_parity] = new_prod
                    if new_sum == k:
                        best = max(best, new_prod)

        return best
