                        nd = (d+1)%4
                        rr,cc = r, c
                        k = turn_at
                        while 0<=rr<n and 0<=cc<m and grid[rr][cc]==seq[k%3]:
                            best = max(best, k+1)
                            rr+=dirs[nd][0]
                            cc+=dirs[nd][1]
