from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = [(1,1), (-1,-1), (1,-1), (-1,1)]
        # clockwise mapping
        next_dir = {0:2, 2:1, 1:3, 3:0}
        # dp[dir][idx][i][j] length of sequence starting at (i,j)
        dp = [[[ [0]*m for _ in range(n) ] for _ in range(3)] for _ in range(4)]
        # expected value for index
        exp = [1,2,0]
        for d, (dx,dy) in enumerate(dirs):
            # determine iteration order
            if dx == 1:
                i_range = range(n-1,-1,-1)
            else:
                i_range = range(n)
            if dy == 1:
                j_range = range(m-1,-1,-1)
            else:
                j_range = range(m)
            for i in i_range:
                for j in j_range:
                    for idx in range(3):
                        if grid[i][j] != exp[idx]:
                            dp[d][idx][i][j] = 0
                        else:
                            ni, nj = i+dx, j+dy
                            if 0 <= ni < n and 0 <= nj < m:
                                dp[d][idx][i][j] = 1 + dp[d][(idx+1)%3][ni][nj]
                            else:
                                dp[d][idx][i][j] = 1
        best = 0
        for i in range(n):
            for j in range(m):
                if grid[i][j] != 1:
                    continue
                for d, (dx,dy) in enumerate(dirs):
                    # walk along this dir
                    ii, jj = i, j
                    t = 0
                    cur_best = 0
                    while 0 <= ii < n and 0 <= jj < m:
                        if grid[ii][jj] != exp[t%3]:
                            break
                        # no turn case
                        if t+1 > best:
                            best = t+1
                        # turn case
                        nd = next_dir[d]
                        nxt_idx = (t+1)%3
                        extra = dp[nd][nxt_idx][ii][jj]
                        if extra:
                            total = t + extra
                            if total > best:
                                best = total
                        t += 1
                        ii += dx
                        jj += dy
        return best
