        n, m = len(skill), len(mana)
        prev = [0] * m
        for i in range(n):
            cur = [0] * m
            for j in range(m):
                if i == 0 and j == 0:
                    cur[j] = skill[i] * mana[j]
                else:
                    left = cur[j-1] if j > 0 else 0
                    up = prev[j]
                    cur[j] = max(left, up) + skill[i] * mana[j]
            prev = cur
        return prev[-1]
