class Solution:
    def sortMatrix(self, grid):
        n = len(grid)
        # collect diagonals
        diags = {}
        for i in range(n):
            for j in range(n):
                d = i - j
                diags.setdefault(d, []).append(grid[i][j])
        # sort each diagonal accordingly
        for d, vals in diags.items():
            vals.sort(reverse=True if d >= 0 else False)
            diags[d] = vals
        # reassign
        idx = {d:0 for d in diags}
        for i in range(n):
            for j in range(n):
                d = i - j
                grid[i][j] = diags[d][idx[d]]
                idx[d] += 1
        return grid
