import sys

MOD = 998244353

def main():
    input_data = sys.stdin.read().strip().split()
    N = int(input_data[0]); M = int(input_data[1]); S = input_data[2]
    # Precompute LIS length for each mask
    LIS_len = [0]*(1<<N)
    for mask in range(1<<N):
        seq = [i for i in range(N) if mask>>i & 1]
        if not seq:
            LIS_len[mask] = 0
            continue
        dp = [1]*len(seq)
        for i in range(len(seq)):
            for j in range(i):
                if seq[j] < seq[i]:
                    dp[i] = max(dp[i], dp[j]+1)
        LIS_len[mask] = max(dp)
    # Precompute positions for each character
    pos = {c: [] for c in 'abcdefghijklmnopqrstuvwxyz'}
    for i,ch in enumerate(S):
        pos[ch].append(i)
    # Compute h_k for k=1..N+1
    h = [0]*(N+2)  # h[0] unused
    for k in range(1, N+2):
        dp = [0]*(1<<N)
        dp[0] = 1
        for _ in range(M):
            ndp = [0]*(1<<N)
            for mask in range(1<<N):
                if dp[mask]==0: continue
                ways = dp[mask]
                # skip character (no match)
                ndp[mask] = (ndp[mask] + ways) % MOD
                # try each letter
                for c in pos:
                    for i in pos[c]:
                        newmask = mask | (1<<i)
                        if LIS_len[newmask] < k:
                            ndp[newmask] = (ndp[newmask] + ways) % MOD
                # also consider letters that don't appear in S
                # they only contribute skip, already counted
            dp = ndp
        h[k] = sum(dp) % MOD
    total = pow(26, M, MOD)
    ans = []
    for k in range(N+1):
        # ans_k = h_{k+2} - h_{k+1}
        val = (h[k+2] - h[k+1]) % MOD
        ans.append(str(val))
    print(' '.join(ans))

if __name__ == "__main__":
    main()
