class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        word = [''] * L
        forced = [''] * L
        # Apply T constraints
        for i, ch in enumerate(str1):
            if ch == 'T':
                for j in range(m):
                    pos = i + j
                    if forced[pos] and forced[pos] != str2[j]:
                        return ""
                    forced[pos] = str2[j]
        # Prepare F constraints
        f_indices = [i for i, ch in enumerate(str1) if ch == 'F']
        if not f_indices:
            # No F, just fill remaining with 'a'
            for pos in range(L):
                word[pos] = forced[pos] if forced[pos] else 'a'
            return "".join(word)
        # For each F, track remaining positions and match count
        rem = [m] * len(f_indices)
        match = [0] * len(f_indices)
        # For each position, list of F indices covering it
        cover = [[] for _ in range(L)]
        for idx, i in enumerate(f_indices):
            for j in range(m):
                cover[i + j].append(idx)
        # Build string
        for pos in range(L):
            # Determine candidate letter
            for ord_l in range(97, 123):  # 'a' to 'z'
                l = chr(ord_l)
                # If forced, must match
                if forced[pos] and forced[pos] != l:
                    continue
                valid = True
                # Check each covering F
                for fi in cover[pos]:
                    new_match = match[fi] + (1 if l == str2[pos - f_indices[fi]] else 0)
                    new_rem = rem[fi] - 1
                    if new_rem == 0 and new_match == m:
                        valid = False
                        break
                if valid:
                    # Assign letter
                    word[pos] = l
                    # Update match and rem
                    for fi in cover[pos]:
                        if l == str2[pos - f_indices[fi]]:
                            match[fi] += 1
                        rem[fi] -= 1
                    break
            else:
                return ""  # no valid letter
        return "".join(word)
