        n, m = len(str1), len(str2)
        L = n + m - 1
        w = ['?'] * L
        # apply T constraints
        for i, c in enumerate(str1):
            if c == 'T':
                for j in range(m):
                    pos = i + j
                    if w[pos] == '?':
                        w[pos] = str2[j]
                    elif w[pos] != str2[j]:
                        return ""
        # fill remaining with 'a'
        for i in range(L):
            if w[i] == '?':
                w[i] = 'a'
