                # check if substring equals str2
                match = True
                for j in range(m):
                    if w[i + j] != str2[j]:
                        match = False
                        break
                if not match:
                    continue
                # need to break equality by changing a position not fixed by T
                pos = i + m - 1  # try last position
                if w[pos] == str2[-1] and w[pos] != '?':
                    # try earlier position
                    found = False
                    for j in range(m - 1, -1, -1):
                        p = i + j
                        if w[p] == '?':
                            # choose smallest char != str2[j]
                            for ch in 'abcdefghijklmnopqrstuvwxyz':
                                if ch != str2[j]:
                                    w[p] = ch
                                    found = True
                                    break
                            if found:
                                break
                    if not found:
                        return ""
                else:
                    # change last position
                    for ch in 'abcdefghijklmnopqrstuvwxyz':
                        if ch != str2[-1]:
                            w[pos] = ch
                            break
        # final check for all T constraints
        for i, c in enumerate(str1):
            if c == 'T':
                for j in range(m):
                    if w[i + j] != str2[j]:
                        return ""
        # final check for all F constraints
        for i, c in enumerate(str1):
            if c == 'F':
                for j in range(m):
                    if w[i + j] != str2[j]:
                        break
                else:
                    return ""
        return ''.join(w)
