class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        word = ['?'] * L

        # Apply T constraints
        for i, c in enumerate(str1):
            if c == 'T':
                for j in range(m):
                    pos = i + j
                    if word[pos] == '?' or word[pos] == str2[j]:
                        word[pos] = str2[j]
                    else:
                        return ""

        # Prepare data for F constraints
        f_indices = [i for i, c in enumerate(str1) if c == 'F']
        count = [0] * n
        equal_flag = [True] * n

        # Initial counts and flags
        for i in f_indices:
            for j in range(m):
                pos = i + j
                if word[pos] != '?':
                    if word[pos] == str2[j]:
                        count[i] += 1
                    else:
                        equal_flag[i] = False
            if count[i] == m and equal_flag[i]:
                return ""

        # Greedy fill
        for pos in range(L):
            if word[pos] != '?':
                continue
            for ch in map(chr, range(ord('a'), ord('z') + 1)):
                ok = True
                for i in f_indices:
                    if i <= pos <= i + m - 1:
                        # simulate
                        if ch == str2[pos - i]:
                            if count[i] + 1 == m and equal_flag[i]:
                                ok = False
                                break
                        else:
                            if equal_flag[i]:
                                # would break equality
                                pass
                if ok:
                    word[pos] = ch
                    # update counts and flags
                    for i in f_indices:
                        if i <= pos <= i + m - 1:
                            if ch == str2[pos - i]:
                                count[i] += 1
                            else:
                                equal_flag[i] = False
                    break
            else:
                return ""

        return ''.join(word)
