import sys
MOD = 998244353

def solve():
    import sys
    input = sys.stdin.readline
    N = int(input().strip())
    A = list(map(int, input().split()))
    from collections import Counter
    # factorize all A_i
    primes = {}
    for a in A:
        x = a
        d = 2
        while d*d <= x:
            while x%d==0:
                primes.setdefault(d, []).append(0)
                x//=d
            d+=1
        if x>1:
            primes.setdefault(x, []).append(0)
    # Build exponent lists
    exp = {p: [] for p in primes}
    for a in A:
        for p in primes:
            cnt=0
            tmp=a
            while tmp%p==0:
                tmp//=p
                cnt+=1
            exp[p].append(cnt)
    ans = 1
    for p, a_list in exp.items():
        # DP over states (current offset after shift, current minimum shift)
        # We'll use dictionary mapping (offset) -> weight, where weight already includes p^{sum of prefixes}
        dp = {0:1}
        min_shift = 0
        for idx, a in enumerate(a_list,1):
            ndp={}
            steps_left = N-idx
            for offset, w in dp.items():
                for s in (a,-a) if a!=0 else (0,):
                    raw = offset + s
                    if raw>=0:
                        new_offset = raw
                        new_w = w * pow(p, (N-idx)*s, MOD) % MOD
                    else:
                        shift = -raw
                        new_offset = 0
                        # shift applies to all future prefixes, so multiply by p^{shift*steps_left}
                        new_w = w * pow(p, (N-idx)*s, MOD) % MOD
                        new_w = new_w * pow(p, shift*steps_left, MOD) % MOD
                    ndp[new_offset] = (ndp.get(new_offset,0)+new_w)%MOD
            dp=ndp
        # sum over all states
        total = 0
        for w in dp.values():
            total = (total + w)%MOD
        ans = ans * total % MOD
    print(ans%MOD)

if __name__ == "__main__":
    solve()
