class Solution:
    def maxFreeTime(self, eventTime: int, k: int, startTime: list[int], endTime: list[int]) -> int:
        n = len(startTime)
        benefits = []
        for i in range(n):
            if i == 0:
                benefits.append(startTime[0])                     # leading gap
            elif i == n - 1:
                benefits.append(eventTime - endTime[-1])           # trailing gap
            else:
                benefits.append(startTime[i + 1] - endTime[i])     # gap after this meeting
        benefits.sort(reverse=True)
        return sum(benefits[:k])
