from typing import List

class Solution:
    def maxFreeTime(self, eventTime: int, k: int, startTime: List[int], endTime: List[int]) -> int:
        n = len(startTime)
        dur = [endTime[i] - startTime[i] for i in range(n)]
        max_len = k + 1
        min_sum = float('inf')
        window_sum = 0
        l = 0
        for r in range(n):
            window_sum += dur[r]
            while r - l + 1 > max_len:
                window_sum -= dur[l]
                l += 1
            if r - l + 1 <= max_len:
                if window_sum < min_sum:
                    min_sum = window_sum
        if min_sum == float('inf'):
            min_sum = 0
        free = eventTime - min_sum
        return max(0, free)
