        dp_list = []
        # initialization for position 0
        dp0 = {}
        orig0 = ord(caption[0]) - 97
        for delta in (-1, 0, 1):
            c = orig0 + delta
            if 0 <= c <= 25:
                cost = abs(delta)
                dp0[(c, 1)] = min(dp0.get((c, 1), INF), cost)
        dp_list.append(dp0)
        # iterate
        for i in range(1, n):
            orig = ord(caption[i]) - 97
            newdp = {}
            for delta in (-1, 0, 1):
                c = orig + delta
                if 0 <= c <= 25:
                    add_cost = abs(delta)
                    for (pc, pl), cost_prev in dp_list[i-1].items():
                        lnew = pl + 1 if c == pc else 1
                        if lnew > 3:
                            lnew = 3
                        new_cost = cost_prev + add_cost
                        key = (c, lnew)
                        if new_cost < newdp.get(key, INF):
                            newdp[key] = new_cost
            dp_list.append(newdp)
        # find minimal cost among final states with runlen==3
        final_dp = dp_list[-1]
        min_cost = INF
        for (c, l), cost in final_dp.items():
            if l == 3 and cost < min_cost:
                min_cost = cost
        if min_cost == INF:
            return ""
        # reconstruction
        res = [''] * n
        # choose smallest char at last pos with runlen==3 and cost==min_cost
        candidates = []
        for (c, l), cost in final_dp.items():
            if l == 3 and cost == min_cost:
                candidates.append(c)
        cur_c = min(candidates)
        cur_l = 3
        cur_cost = min_cost
        res[n-1] = chr(cur_c + 97)
        for i in range(n-1, 0, -1):
            orig = ord(caption[i]) - 97
            # we need to find prev state
            best_prev_c = None
            best_prev_l = None
            best_prev_cost = None
            for (pc, pl), cost_prev in dp_list[i-1].items():
                # transition to cur_c
                lnew = pl + 1 if cur_c == pc else 1
                if lnew > 3:
                    lnew = 3
                if lnew != cur_l:
                    continue
                if cost_prev + abs(orig - cur_c) != cur_cost:
                    continue
                if best_prev_c is None or pc < best_prev_c:
                    best_prev_c = pc
                    best_prev_l = pl
                    best_prev_cost = cost_prev
            # set
            cur_c = best_prev_c
            cur_l = best_prev_l
            cur_cost = best_prev_cost
            res[i-1] = chr(cur_c + 97)
        return "".join(res)
