    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        INF = 10**15
        # dp[i][c][l] minimal cost up to i ending with char c (0-25) and run length l (1,2,3)
        dp = [[[INF]*4 for _ in range(26)] for _ in range(n)]
        prev = [[[None]*4 for _ in range(26)] for _ in range(n)]
        def dist(a, b):
            return abs(ord(a)-ord(b))
        for c in range(26):
            dp[0][c][1] = dist(caption[0], chr(c+97))
            prev[0][c][1] = None
        for i in range(1, n):
            ch = caption[i]
            for pc in range(26):
                for pl in (1,2,3):
                    if dp[i-1][pc][pl] == INF:
                        continue
                    base = dp[i-1][pc][pl]
                    for c in range(26):
                        cost = base + abs(ord(ch)-ord(c+97))
                        if c == pc:
                            nl = min(pl+1, 3)
                            if cost < dp[i][c][nl] or (cost == dp[i][c][nl] and (prev[i][c][nl] is None or
                                (pc < prev[i][c][nl][0] or (pc==prev[i][c][nl][0] and pl < prev[i][c][nl][1])))):
                                dp[i][c][nl] = cost
                                prev[i][c][nl] = (pc, pl)
                        else:
                            if pl == 3:
                                nl = 1
                                if cost < dp[i][c][nl] or (cost == dp[i][c][nl] and (prev[i][c][nl] is None or
                                    (pc < prev[i][c][nl][0] or (pc==prev[i][c][nl][0] and pl < prev[i][c][nl][1])))):
                                    dp[i][c][nl] = cost
                                    prev[i][c][nl] = (pc, pl)
        best = INF
        best_c = -1
        for c in range(26):
            if dp[n-1][c][3] < best:
                best = dp[n-1][c][3]
                best_c = c
        if best == INF:
            return ""
        # reconstruct
        res = ['']*n
        i = n-1
        c = best_c
        l = 3
        while i >= 0:
            res[i] = chr(c+97)
            p = prev[i][c][l]
            if p is None:
                break
            pc, pl = p
            i -= 1
            c, l = pc, pl
        return ''.join(res)
