class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        INF = 10**9
        # Precompute reachable chars per position
        reach = []
        for ch in caption:
            idx = ord(ch) - 97
            lst = [idx]
            if idx > 0: lst.append(idx-1)
            if idx < 25: lst.append(idx+1)
            reach.append(lst)

        # DP structures
        prev_dp = {}
        prev_parent = {}
        for c in reach[0]:
            cost = 0 if c == (ord(caption[0]) - 97) else 1
            prev_dp[(c, 0)] = cost  # start new group with length 1 -> l=0 means group length 1? we use l=0 for group length 1
            # Actually we treat l=0 as length 1, l=1 as length 2, l=2 as length>=3 (reset)
            # But to simplify, we keep l=0 for length 1, l=1 for length 2, l=2 for >=3
            # So initial l=0
            prev_parent[(c, 0)] = None

        for pos in range(1, n):
            cur_dp = {}
            cur_parent = {}
            for pc, pl in prev_dp:
                prev_cost = prev_dp[(pc, pl)]
                for c in reach[pos]:
                    add = 0 if c == (ord(caption[pos]) - 97) else 1
                    new_cost = prev_cost + add
                    if c == pc:
                        if pl == 0:
                            nl = 1
                        elif pl == 1:
                            nl = 2
                        else:
                            nl = 0
                    else:
                        nl = 0
                    key = (c, nl)
                    if key not in cur_dp or new_cost < cur_dp[key]:
                        cur_dp[key] = new_cost
                        cur_parent[key] = (pc, pl)
                    elif new_cost == cur_dp[key]:
                        # tie-break by lex order later
                        pass
            prev_dp, prev_parent = cur_dp, cur_parent

        # Find minimal cost among states with nl==0 (group length 1 or 3+)
        best_cost = INF
        best_keys = []
        for (c, nl), cost in prev_dp.items():
            if nl == 0:
                if cost < best_cost:
                    best_cost = cost
                    best_keys = [(c, nl)]
                elif cost == best_cost:
                    best_keys.append((c, nl))
        if best_cost == INF:
            return ""
        # Reconstruct candidates
        best_string = None
        for key in best_keys:
            s = [''] * n
            cur = key
            for pos in range(n-1, -1, -1):
                c, nl = cur
                s[pos] = chr(c + 97)
                cur = prev_parent.get(cur)
            cand = ''.join(s)
            if best_string is None or cand < best_string:
                best_string = cand
        return best_string
