class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        INF = 10**9
        # dp2[i][c][l] minimal cost to finish from position i
        # c: 0-25 letter, 26 means None (no current run)
        # l: 0(no run),1,2,3 (>=3)
        dp2 = [[[INF]*4 for _ in range(27)] for _ in range(n+1)]
        for c in range(27):
            for l in range(4):
                dp2[n][c][l] = 0 if l>=3 else INF
        # Precompute char codes
        codes = [ord(ch)-97 for ch in caption]
        for i in range(n-1, -1, -1):
            cur = codes[i]
            for c in range(27):
                for l in range(4):
                    best = INF
                    # try all new_c
                    for new_c in range(26):
                        cost = abs(cur - new_c)
                        if c == 26:  # no current run
                            l2 = 1
                        else:
                            if new_c == c:
                                l2 = 3 if l==3 else min(l+1,3)
                            else:
                                l2 = 1
                        nxt = dp2[i+1][new_c][l2]
                        if nxt + cost < best:
                            best = nxt + cost
                    dp2[i][c][l] = best
        mincost = dp2[0][26][0]
        if mincost >= INF:
            return ""
        # Reconstruct lexicographically smallest string
        res = []
        c = 26
        l = 0
        for i in range(n):
            cur = codes[i]
            chosen = None
            for new_c in range(26):
                cost = abs(cur - new_c)
                if c == 26:
                    l2 = 1
                else:
                    if new_c == c:
                        l2 = 3 if l==3 else min(l+1,3)
                    else:
                        l2 = 1
                if dp2[i+1][new_c][l2] + cost == dp2[i][c][l]:
                    chosen = new_c
                    break
            res.append(chr(chosen+97))
            c = chosen
            l = l2
        return "".join(res)
