    grid = [list(next(it).strip()) for _ in range(N)]

    # adjacency by label
    adj = [[{} for _ in range(N)] for _ in range(N)]
    for i in range(N):
        for j in range(N):
            c = grid[i][j]
            if c != '-':
                adj[i][j].setdefault(c, []).append(j)

    # precompute for each node: dict label -> list of targets
    out = [dict() for _ in range(N)]
    for i in range(N):
        d = dict()
        for j in range(N):
            c = grid[i][j]
            if c != '-':
                d.setdefault(c, []).append(j)
        out[i] = d

    INF = -1
    ans = [[-1]*N for _ in range(N)]

    for s in range(N):
        for t in range(N):
            dist = [[-1]*N for _ in range(N)]
            q = deque()
            dist[s][t] = 0
            q.append((s, t))
            best = INF
            while q:
                u, v = q.popleft()
                d = dist[u][v]
                # even length center
                if u == v:
                    best = min(best, d*2)
                # odd length center via edge u->v
                if grid[u][v] != '-':
                    best = min(best, d*2 + 1)
                # expand
                for c, us in out[u].items():
                    vs = out[v].get(c)
                    if vs:
                        for u2 in us:
                            for v2 in vs:
                                if dist[u2][v2] == -1:
                                    dist[u2][v2] = d + 1
                                    q.append((u2, v2))
            ans[s][t] = best

    out_lines = [' '.join(map(str, row)) for row in ans]
    sys.stdout.write('\n'.join(out_lines))

if __name__ == "__main__":
