from typing import List
import math

class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        m = len(target)
        full = (1 << m) - 1
        INF = 10**18
        dp = [INF] * (1 << m)
        dp[0] = 0

        # precompute lcm for all subsets
        lcms = [1] * (1 << m)
        for mask in range(1, 1 << m):
            l = 1
            for i in range(m):
                if mask & (1 << i):
                    l = l * target[i] // math.gcd(l, target[i])
            lcms[mask] = l

        for num in nums:
            incs = [INF] * (1 << m)
            for mask in range(1, 1 << m):
                l = lcms[mask]
                k = (num + l - 1) // l
                incs[mask] = k * l - num
            new_dp = dp[:]
            for mask in range(1 << m):
                if dp[mask] == INF:
                    continue
                for s in range(1, 1 << m):
                    cost = incs[s]
                    if cost == INF:
                        continue
                    nm = mask | s
                    if new_dp[nm] > dp[mask] + cost:
                        new_dp[nm] = dp[mask] + cost
            dp = new_dp
        return dp[full]
