        lcm_subset = [1] * (1 << t)
        for mask in range(1, 1 << t):
            l = 1
            for i in range(t):
                if mask & (1 << i):
                    l = l * target[i] // math.gcd(l, target[i])
            lcm_subset[mask] = l

        for val in nums:
            # compute cost for each subset
            cost_subset = [0] * (1 << t)
            for mask in range(1, 1 << t):
                L = lcm_subset[mask]
                inc = (-val) % L
                cost_subset[mask] = inc
            # DP update
            for mask in range(full, -1, -1):
                if dp[mask] == INF:
                    continue
                for sub in range(1, 1 << t):
                    new_mask = mask | sub
                    new_cost = dp[mask] + cost_subset[sub]
                    if new_cost < dp[new_mask]:
                        dp[new_mask] = new_cost
        return dp[full]
