from math import gcd
from typing import List

class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        n = len(nums)
        m = len(target)

        def lcm(a, b):
            return a // gcd(a, b) * b

        # precompute lcm for all subsets of targets
        subset_lcm = {}
        for mask in range(1, 1 << m):
            lc = 1
            for i in range(m):
                if mask & (1 << i):
                    lc = lcm(lc, target[i])
            subset_lcm[mask] = lc

        # helper to compute minimal cost for a given lcm value
        def min_cost(lc):
            best = float('inf')
            for a in nums:
                rem = a % lc
                inc = (lc - rem) % lc
                if inc < best:
                    best = inc
            return best

        # generate all partitions of target indices
        indices = list(range(m))
        best_ans = float('inf')

        def dfs(pos, current_parts):
            nonlocal best_ans
            if pos == m:
                total = 0
                for part in current_parts:
                    lc = subset_lcm[part]
                    total += min_cost(lc)
                if total < best_ans:
                    best_ans = total
                return
            # try to add current index to existing parts
            for i in range(len(current_parts)):
                dfs(pos + 1, current_parts[:i] + [current_parts[i] | (1 << indices[pos])] + current_parts[i+1:])
            # start new part
            dfs(pos + 1, current_parts + [(1 << indices[pos])])

        dfs(0, [])
        return best_ans
