import math
from typing import List

class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        k = len(target)
        full = (1 << k) - 1

        # precompute lcm for each non-empty subset of targets
        lcm_subset = {}
        for mask in range(1, full + 1):
            l = 1
            for i in range(k):
                if mask >> i & 1:
                    l = math.lcm(l, target[i])
            lcm_subset[mask] = l

        INF = 10**18
        best_cost = [INF] * (full + 1)  # best cost to cover subset with one element

        # For each nums element, compute cost for each subset
        for v in nums:
            for mask in range(1, full + 1):
                l = lcm_subset[mask]
                r = v % l
                inc = (l - r) % l
                if inc < best_cost[mask]:
                    best_cost[mask] = inc

        # DP over subsets
        dp = [INF] * (full + 1)
        dp[0] = 0
        for mask in range(1, full + 1):
            sub = mask
            while sub:
                cost_sub = best_cost[sub]
                if cost_sub < INF:
                    dp[mask] = min(dp[mask], dp[mask ^ sub] + cost_sub)
                sub = (sub - 1) & mask

        return dp[full]
