import sys
from collections import deque

def solve() -> None:
    it = iter(sys.stdin.read().strip().split())
    try:
        N = int(next(it))
    except StopIteration:
        return
    M = int(next(it))
    A = int(next(it))
    B = int(next(it))
    bad = []
    for _ in range(M):
        l = int(next(it)); r = int(next(it))
        bad.append((l, r))
    bad.sort()
    def is_bad(x: int) -> bool:
        lo, hi = 0, M-1
        while lo <= hi:
            mid = (lo+hi)//2
            l, r = bad[mid]
            if l <= x <= r:
                return True
            if x < l:
                hi = mid-1
            else:
                lo = mid+1
        return False
    if is_bad(N):
        print("No")
        return
    q = deque([1])
    seen = {1}
    while q:
        x = q.popleft()
        if x == N:
            print("Yes")
            return
        for step in range(A, B+1):
            nx = x + step
            if nx > N or nx in seen or is_bad(nx):
                continue
            seen.add(nx)
            q.append(nx)
    print("No")

if __name__ == "__main__":
    solve()
