import sys
import bisect

def solve():
    import sys
    sys.setrecursionlimit(1 << 25)
    input = sys.stdin.readline
    N, M = map(int, input().split())
    L = [0]*M
    R = [0]*M
    op_type = [0]*M
    op1_idx = []
    op2_idx = []
    for i in range(M):
        l,r = map(int, input().split())
        L[i]=l; R[i]=r
        if i%3==0:
            op_type[i]=0
        elif i%3==1:
            op_type[i]=1
            op1_idx.append(i)
        else:
            op_type[i]=2
            op2_idx.append(i)
    # build BIT for op1 intervals
    if op1_idx:
        vals = sorted(set(L[i] for i in op1_idx))
        pos = {v:i for i,v in enumerate(vals)}
        size = len(vals)
        bitR = [(-1,-1)]*(size+1)  # (R, idx)
        def bit_update(i, val):
            i+=1
            while i<=size:
                if val[0] > bitR[i][0]:
                    bitR[i]=val
                i+=i&-i
        def bit_query(i):
            res=(-1,-1)
            i+=1
            while i>0:
                if bitR[i][0] > res[0]:
                    res=bitR[i]
                i-=i&-i
            return res
        for idx in op1_idx:
            l=L[idx]; r=R[idx]
            bit_update(pos[l], (r, idx))
    else:
        vals=[]; pos={}; bitR=[(-1,-1)]
    # function to cover interval [a,b] with op1s
    def cover_interval(a,b):
        cur=a
        chosen=[]
        while cur<=b:
            # find max l <= cur
            i = bisect.bisect_right(vals, cur)-1
            if i<0:
                return None
            r, idx = bit_query(i)
            if r<cur:
                return None
            chosen.append(idx)
            cur=r+1
        return chosen
    # option 0: no op2
    best_cost=None
    best_ops=None
    if op1_idx:
        res = cover_interval(1,N)
        if res is not None:
            best_cost=len(res)
            best_ops=[0]*M
            for i in res:
                best_ops[i]=1
    else:
        # no op1, cannot cover
        pass
    # option 1: use one op2
    for oi in op2_idx:
        # intersection is [L[oi],R[oi]]
        res = cover_interval(L[oi], R[oi])
        if res is not None:
            cost=1+len(res)
            if best_cost is None or cost<best_cost:
                best_cost=cost
                best_ops=[0]*M
                best_ops[oi]=2
                for idx in res:
                    best_ops[idx]=1
    # option 2: try two op2 to empty intersection
    if len(op2_idx)>=2:
        # find max L and min R among all op2
        maxL = max(L[i] for i in op2_idx)
        minR = min(R[i] for i in op2_idx)
        if maxL>minR:
            # choose any two with L=maxL and R=minR
            iL=None; iR=None
            for i in op2_idx:
                if L[i]==maxL and iL is None:
                    iL=i
                if R[i]==minR and iR is None:
                    iR=i
            if iL is None: iL=op2_idx[0]
            if iR is None: iR=op2_idx[1]
            if iL==iR:
                # need third
                pass
            else:
                if best_cost is None or 2<best_cost:
                    best_cost=2
                    best_ops=[0]*M
                    best_ops[iL]=2
                    best_ops[iR]=2
        else:
            # try any pair that makes maxL>minR
            # find op2 with L > minR
            candL=[]
            for i in op2_idx:
                if L[i]>minR:
                    candL.append(i)
            candR=[]
            for i in op2_idx:
                if R[i]<maxL:
                    candR.append(i)
            if candL:
                iL=candL[0]
                # choose any other
                iR=op2_idx[0] if op2_idx[0]!=iL else (op2_idx[1] if len(op2_idx)>1 else None)
                if iR is not None:
                    if best_cost is None or 2<best_cost:
                        best_cost=2
                        best_ops=[0]*M
                        best_ops[iL]=2
                        best_ops[iR]=2
            if candR:
                iR=candR[0]
                iL=op2_idx[0] if op2_idx[0]!=iR else (op2_idx[1] if len(op2_idx)>1 else None)
                if iL is not None:
                    if best_cost is None or 2<best_cost:
                        best_cost=2
                        best_ops=[0]*M
                        best_ops[iL]=2
                        best_ops[iR]=2
    if best_cost is None:
        print(-1)
    else:
        print(best_cost)
        print(' '.join(map(str, best_ops)))

if __name__ == "__main__":
    solve()
