import sys
sys.setrecursionlimit(1 << 25)

def solve():
    import sys
    input = sys.stdin.readline
    H, W = map(int, input().split())
    F = [list(map(int, input().split())) for _ in range(H)]
    Q = int(input())
    queries = []
    for _ in range(Q):
        a,b,y,c,d,z = map(int, input().split())
        queries.append((a-1,b-1,y,c-1,d-1,z))
    # Precompute cell list sorted by height descending
    cells = []
    for i in range(H):
        for j in range(W):
            cells.append((F[i][j], i, j))
    cells.sort(reverse=True)
    # DSU implementation
    class DSU:
        __slots__ = ('p', 'r')
        def __init__(self, n):
            self.p = list(range(n))
            self.r = [0]*n
        def find(self, x):
            while self.p[x]!=x:
                self.p[x]=self.p[self.p[x]]
                x=self.p[x]
            return x
        def union(self, a,b):
            a=self.find(a); b=self.find(b)
            if a==b: return
            if self.r[a]<self.r[b]:
                a,b=b,a
            self.p[b]=a
            if self.r[a]==self.r[b]:
                self.r[a]+=1
    # mapping from (i,j) to id
    id_map = [[i*W+j for j in range(W)] for i in range(H)]
    # Binary search bounds
    lows = [0]*Q
    highs = [0]*Q
    for idx,(a,b,y,c,d,z) in enumerate(queries):
        highs[idx] = min(y,z)
    # iterative binary search
    while True:
        mids_dict = {}
        any_pending = False
        for idx in range(Q):
            if lows[idx] < highs[idx]:
                any_pending = True
                mid = (lows[idx]+highs[idx]+1)//2
                mids_dict.setdefault(mid, []).append(idx)
        if not any_pending:
            break
        # process mids in descending order
        sorted_mids = sorted(mids_dict.keys(), reverse=True)
        dsu = DSU(H*W)
        active = [False]*(H*W)
        ptr = 0
        for mid in sorted_mids:
            while ptr < len(cells) and cells[ptr][0] >= mid:
                _, i, j = cells[ptr]
                idx_cell = id_map[i][j]
                active[idx_cell] = True
                for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                    ni, nj = i+di, j+dj
                    if 0<=ni<H and 0<=nj<W:
                        nid = id_map[ni][nj]
                        if active[nid]:
                            dsu.union(idx_cell, nid)
                ptr += 1
            for qi in mids_dict[mid]:
                a,b,y,c,d,z = queries[qi]
                if dsu.find(id_map[a][b]) == dsu.find(id_map[c][d]):
                    lows[qi] = mid
                else:
                    highs[qi] = mid-1
    # compute answers
    out = []
    for idx,(a,b,y,c,d,z) in enumerate(queries):
        L = lows[idx]
        L = min(L, min(y,z))
        ans = y + z - 2*L
        out.append(str(ans))
    print("\n".join(out))

if __name__ == "__main__":
    solve()
```

