import sys
import threading
import random

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    P = [int(next(it)) for _ in range(n)]

    class Node:
        __slots__ = ("val", "prio", "size", "left", "right")
        def __init__(self, val):
            self.val = val
            self.prio = random.randint(1, 1 << 30)
            self.size = 1
            self.left = None
            self.right = None

    def upd(node):
        if node:
            node.size = 1
            if node.left:
                node.size += node.left.size
            if node.right:
                node.size += node.right.size

    def split(node, k):
        """split first k nodes to left"""
        if not node:
            return (None, None)
        if (node.left.size if node.left else 0) >= k:
            left, right = split(node.left, k)
            node.left = right
            upd(node)
            return (left, node)
        else:
            left, right = split(node.right, k - (node.left.size if node.left else 0) - 1)
            node.right = left
            upd(node)
            return (node, right)

    def merge(a, b):
        if not a or not b:
            return a or b
        if a.prio > b.prio:
            a.right = merge(a.right, b)
            upd(a)
            return a
        else:
            b.left = merge(a, b.left)
            upd(b)
            return b

    root = None
    for i in range(1, n + 1):
        pos = P[i - 1] - 1  # 0‑based
        node = Node(i)
        left, right = split(root, pos)
        root = merge(merge(left, node), right)

    res = []
    stack = [root]
    while stack:
        node = stack.pop()
        if node:
            stack.append(node.right)
            res.append(str(node.val))
            stack.append(node.left)
    sys.stdout.write(" ".join(res))

if __name__ == "__main__":
    threading.Thread(target=solve).start()
```

