class Solution:
    def separateSquares(self, squares: list[list[int]]) -> float:
        total_area = 0
        min_y = float('inf')
        max_y = -float('inf')
        for x, y, l in squares:
            area = l * l
            total_area += area
            min_y = min(min_y, y)
            max_y = max(max_y, y + l)

        target = total_area / 2.0

        def area_above(line: float) -> float:
            s = 0.0
            for x, y, l in squares:
                if line <= y:
                    s += l * l
                elif line >= y + l:
                    continue
                else:
                    s += (y + l - line) * l
            return s

        lo, hi = min_y, max_y
        for _ in range(60):  # enough for 1e-5 precision
            mid = (lo + hi) / 2
            if area_above(mid) > target:
                lo = mid
            else:
                hi = mid
        return (lo + hi) / 2
