            max_y = max(max_y, y + l)
        target = total_area / 2.0
        def above_area(th):
            s = 0.0
            for x, y, l in squares:
                top = y + l
                if th < y:
                    s += l * l
                elif th >= top:
                    s += 0.0
                else:
                    s += (top - th) * l
            return s
        lo, hi = min_y, max_y
        for _ in range(80):
            mid = (lo + hi) / 2
            if above_area(mid) > target:
                lo = mid
            else:
                hi = mid
        return (lo + hi) / 2
