class Solution:
    def separateSquares(self, squares):
        lo = min(y for _, y, _ in squares)
        hi = max(y + l for _, y, l in squares)
        total_area = sum(l * l for _, _, l in squares)

        def area_below(y):
            s = 0.0
            for _, y0, l in squares:
                y1 = y0 + l
                if y <= y0:
                    continue
                elif y >= y1:
                    s += l * l
                else:
                    h = y - y0
                    s += h * h
            return s

        for _ in range(60):  # enough for 1e-5 precision
            mid = (lo + hi) / 2
            if area_below(mid) * 2 < total_area:
                lo = mid
            else:
                hi = mid
        return (lo + hi) / 2
