class Solution:
    def maxScore(self, points: list[int], m: int) -> int:
        import math
        n = len(points)
        # maximum possible minimum score is bounded by the smallest points[i] times how many times we can visit it
        # In best case we visit each index roughly m/n times, so upper bound:
        high = min(points) * (m // n) + 1
        low = 0
        while low < high:
            mid = (low + high) // 2
            # compute required visits to achieve at least mid in each position
            total = 0
            for p in points:
                total += (mid + p - 1) // p
                if total > m:
                    break
            if total <= m:
                low = mid + 1
            else:
                high = mid
        return low - 1
