class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        from collections import deque

        n = len(nums)
        m = len(queries)

        def can(k: int) -> bool:
            # build flow graph for first k queries
            N = 1 + k + n + 1  # source + queries + indices + sink
            src = 0
            sink = N - 1
            graph = [[] for _ in range(N)]

            def add_edge(u, v, c):
                graph[u].append([v, c, len(graph[v])])
                graph[v].append([u, 0, len(graph[u]) - 1])

            # source to queries
            for j in range(k):
                l, r, val = queries[j]
                add_edge(src, 1 + j, val)

                # query to indices
                for i in range(l, r + 1):
                    add_edge(1 + j, 1 + k + i, val)

            # indices to sink
            total_need = 0
            for i in range(n):
                need = nums[i]
                if need > 0:
                    add_edge(1 + k + i, sink, need)
                    total_need += need

            # Dinic
            flow = 0
            INF = 10**9

            while True:
                level = [-1] * N
                q = deque([src])
                level[src] = 0
                while q:
                    u = q.popleft()
                    for v, cap, rev in graph[u]:
                        if cap > 0 and level[v] == -1:
                            level[v] = level[u] + 1
                            q.append(v)
                if level[sink] == -1:
                    break

                it = [0] * N

                def dfs(u, f):
                    if u == sink:
                        return f
                    for i in range(it[u], len(graph[u])):
                        v, cap, rev = graph[u][i]
                        if cap > 0 and level[u] + 1 == level[v]:
                            ret = dfs(v, min(f, cap))
                            if ret:
                                graph[u][i][1] -= ret
                                graph[v][rev][1] += ret
                                return ret
                        it[u] += 1
                    return 0

                while True:
                    pushed = dfs(src, INF)
                    if not pushed:
                        break
                    flow += pushed
            return flow == total_need

        # binary search minimal k
        lo, hi = 1, m
        ans = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if can(mid):
                ans = mid
                hi = mid - 1
            else:
                lo = mid + 1
        return ans
