class Solution:
    def minZeroArray(self, nums: list[int], queries: list[list[int]]) -> int:
        from functools import lru_cache
        n = len(nums)
        # Convert nums to tuple for hashing
        target = tuple([0]*n)
        @lru_cache(maxsize=None)
        def dfs(idx: int, state: tuple[int]) -> bool:
            if state == target:
                return True
            if idx == len(queries):
                return False
            l, r, v = queries[idx]
            # generate all subsets of indices in [l,r] that can be decremented
            # We use bitmask over the subrange length
            sub_len = r - l + 1
            # precompute possible masks that keep all values >= v
            for mask in range(1 << sub_len):
                new_state = list(state)
                ok = True
                for i in range(sub_len):
                    if mask & (1 << i):
                        pos = l + i
                        if new_state[pos] < v:
                            ok = False
                            break
                        new_state[pos] -= v
                if not ok:
                    continue
                if dfs(idx + 1, tuple(new_state)):
                    return True
            return False

        for k in range(1, len(queries) + 1):
            if dfs(0, tuple(nums)):
                return k
        return -1
