        INF = -10**15
        dp = [[[INF]*3 for _ in range(n)] for _ in range(m)]
        # start
        val0 = coins[0][0]
        if val0 >= 0:
            dp[0][0][0] = val0
        else:
            # can neutralize at start
            dp[0][0][0] = val0
            dp[0][0][1] = 0
        for i in range(m):
            for j in range(n):
                if i==0 and j==0: continue
                for k in range(3):
                    best = INF
                    # from top
                    if i>0 and dp[i-1][j][k]!=INF:
                        best = max(best, dp[i-1][j][k])
                    # from left
                    if j>0 and dp[i][j-1][k]!=INF:
                        best = max(best, dp[i][j-1][k])
                    if best==INF: continue
                    val = coins[i][j]
                    if val>=0:
                        dp[i][j][k] = max(dp[i][j][k], best+val)
                    else:
                        # don't neutralize
                        dp[i][j][k] = max(dp[i][j][k], best+val)
                        # neutralize if possible
                        if k>0:
                            dp[i][j][k-1] = max(dp[i][j][k-1], best)
        return max(dp[m-1][n-1])
