class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        # contributions for each of the 4 linear combinations
        # 0: X+Y, 1: X-Y, 2: -X+Y, 3: -X-Y
        sums = [0, 0, 0, 0]
        negs = [0, 0, 0, 0]
        best = 0
        for ch in s:
            # combo 0
            if ch in 'EN':
                sums[0] += 1
            else:
                sums[0] -= 1
                negs[0] += 1
            # combo 1
            if ch in 'ES':
                sums[1] += 1
            else:
                sums[1] -= 1
                negs[1] += 1
            # combo 2
            if ch in 'WN':
                sums[2] += 1
            else:
                sums[2] -= 1
                negs[2] += 1
            # combo 3
            if ch in 'WS':
                sums[3] += 1
            else:
                sums[3] -= 1
                negs[3] += 1
            for c in range(4):
                val = sums[c] + 2 * min(k, negs[c])
                if val > best:
                    best = val
        return best
