class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        n = len(s)
        dirs = {'N': (0,1),'S':(0,-1),'E':(1,0),'W':(-1,0)}
        vecs = [(0,1),(0,-1),(1,0),(-1,0)]
        best = 0
        for sx in (1,-1):
            for sy in (1,-1):
                base_sum = 0
                sum_sel = 0
                sel = []  # min-heap for selected diffs (size <= k)
                rem = []  # max-heap for remaining diffs
                max_at_t = float('-inf')
                for i,ch in enumerate(s):
                    ox,oy = dirs[ch]
                    val0 = sx*ox + sy*oy
                    base_sum += val0
                    # compute best possible val if changed
                    best_val = max(sx*x + sy*y for x,y in vecs)
                    diff = best_val - val0
                    if diff > 0:
                        if len(sel) < k:
                            heapq.heappush(sel, diff)
                            sum_sel += diff
                        else:
                            if sel and diff > sel[0]:
                                smallest = heapq.heappop(sel)
                                sum_sel -= smallest
                                heapq.heappush(sel, diff)
                                sum_sel += diff
                    cur = base_sum + sum_sel
                    if cur > max_at_t:
                        max_at_t = cur
                if max_at_t > best:
                    best = max_at_t
        return best
