class Solution:
    def maxFrequency(self, nums: list[int], k: int) -> int:
        n = len(nums)
        current_k = nums.count(k)
        max_len = 0
        i = 0
        while i < n:
            v = nums[i]
            if v != k:
                j = i
                while j < n and nums[j] == v:
                    j += 1
                max_len = max(max_len, j - i)
                i = j
            else:
                i += 1
        return current_k + max_len
