import sys

def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    it = iter(input_data)
    N = int(next(it)); M = int(next(it))
    edges = []
    for _ in range(M):
        x = int(next(it))-1
        y = int(next(it))-1
        z = int(next(it))
        edges.append((x, y, z))
    ans = [0]*N
    # process each bit separately
    for bit in range(31):
        parent = list(range(N))
        parity = [0]*N  # parity to root
        sz = [1]*N
        def find(x):
            if parent[x]!=x:
                r = find(parent[x])
                parity[x] ^= parity[parent[x]]
                parent[x] = r
            return parent[x]
        ok = True
        for x,y,z in edges:
            w = (z>>bit)&1
            rx = find(x); ry = find(y)
            px = parity[x]; py = parity[y]
            if rx==ry:
                if (px ^ py) != w:
                    ok = False
                    break
            else:
                # union by size
                if sz[rx] < sz[ry]:
                    rx, ry = ry, rx
                    px, py = py, px
                parent[ry] = rx
                parity[ry] = px ^ py ^ w
                sz[rx] += sz[ry]
        if not ok:
            print(-1)
            return
        # compute component assignments
        comp = {}
        for i in range(N):
            r = find(i)
            p = parity[i]
            if r not in comp:
                comp[r] = [0,0]  # count of 0 and 1 relative to root=0
            if p==0:
                comp[r][0] += 1
            else:
                comp[r][1] += 1
        # choose root value per component
        root_val = {}
        for r,(c0,c1) in comp.items():
            if c1 <= c0:
                root_val[r] = 0
            else:
                root_val[r] = 1
        # set bits
        for i in range(N):
            r = find(i)
            p = parity[i]
            if root_val[r]==0:
                val = p
            else:
                val = p ^ 1
            if val:
                ans[i] |= (1<<bit)
    print(' '.join(map(str, ans)))

if __name__ == "__main__":
    solve()
