import sys

def solve() -> None:
    sys.setrecursionlimit(1 << 25)
    it = iter(sys.stdin.read().split())
    try:
        N = int(next(it))
    except StopIteration:
        return
    M = int(next(it))
    adj = [[] for _ in range(N)]
    for _ in range(M):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        z = int(next(it))
        adj[u].append((v, z))
        adj[v].append((u, z))

    visited = [False] * N
    val = [0] * N
    ans = [0] * N

    for i in range(N):
        if visited[i]:
            continue
        stack = [i]
        visited[i] = True
        comp_nodes = [i]
        val[i] = 0
        ok = True
        while stack:
            u = stack.pop()
            for v, z in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    val[v] = val[u] ^ z
                    stack.append(v)
                    comp_nodes.append(v)
                else:
                    if val[u] ^ val[v] != z:
                        ok = False
                        break
            if not ok:
                break
        if not ok:
            print(-1)
            return
        # compute t
        t = 0
        for k in range(31):  # Z_i <= 1e9 < 2^30, but use 31 bits
            cnt0 = cnt1 = 0
            bit = 1 << k
            for u in comp_nodes:
                if val[u] & bit:
                    cnt1 += 1
                else:
                    cnt0 += 1
            if cnt1 > cnt0:
                t |= bit
        for u in comp_nodes:
            ans[u] = t ^ val[u]

    print(' '.join(map(str, ans)))

if __name__ == "__main__":
