class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True
        n = len(s)
        last = [0] * 26
        for i, ch in enumerate(s):
            last[ord(ch) - 97] = i
        segments = 0
        start = 0
        for i, ch in enumerate(s):
            if i == last[ord(ch) - 97]:
