class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True
        n = len(s)
        first = {}
        last = {}
        for i, ch in enumerate(s):
            if ch not in first:
                first[ch] = i
            last[ch] = i
        segments = 0
        i = 0
        while i < n:
            cur_end = last[s[i]]
            j = i
            while j <= cur_end:
                cur_end = max(cur_end, last[s[j]])
                j += 1
            if cur_end - i + 1 < n:
                segments += 1
            i = cur_end + 1
        return segments >= k
