class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        n = len(s)
        if k == 0:
            return True
        last = {c: i for i, c in enumerate(s)}
        max_last = -1
        parts = 0
        for i, c in enumerate(s):
            max_last = max(max_last, last[c])
            if i == max_last:
                parts += 1
        # If there are no valid partitions, cannot form any special substring
        return parts >= k and parts > 0
