import sys
MOD = 998244353

# NTT implementation
def ntt(a, invert):
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]
    length = 2
    root = pow(3, (MOD-1)//n, MOD)
    if invert:
        root = pow(root, MOD-2, MOD)
    while length <= n:
        wlen = pow(root, n // length, MOD)
        for i in range(0, n, length):
            w = 1
            for j in range(i, i + length//2):
                u = a[j]
                v = a[j + length//2] * w % MOD
                a[j] = (u + v) % MOD
                a[j + length//2] = (u - v + MOD) % MOD
                w = w * wlen % MOD
        length <<= 1
    if invert:
        n_inv = pow(n, MOD-2, MOD)
        for i in range(n):
            a[i] = a[i] * n_inv % MOD

def multiply(a, b):
    n = 1
    while n < len(a) + len(b) - 1:
        n <<= 1
    fa = a + [0]*(n-len(a))
    fb = b + [0]*(n-len(b))
    ntt(fa, False)
    ntt(fb, False)
    for i in range(n):
        fa[i] = fa[i] * fb[i] % MOD
    ntt(fa, True)
    return fa[:len(a)+len(b)-1]

def poly_product(pols):
    def rec(l, r):
        if l == r:
            return pols[l]
        m = (l + r) // 2
        left = rec(l, m)
        right = rec(m+1, r)
        return multiply(left, right)
    return rec(0, len(pols)-1)

def main():
    N = int(sys.stdin.readline())
    d = [len(str(i)) for i in range(1, N+1)]
    pow10 = [1]*(max(d)+1)
    for i in range(1, len(pow10)):
        pow10[i] = pow10[i-1]*10 % MOD

    polys = [[1, pow10[di]] for di in d]
    coeff = poly_product(polys)  # size N+1
    # factorials
    fact = [1]*(N+1)
    for i in range(1, N+1):
        fact[i] = fact[i-1]*i%MOD
    invfact = [1]*(N+1)
    invfact[N] = pow(fact[N], MOD-2, MOD)
    for i in range(N,0,-1):
        invfact[i-1] = invfact[i]*i%MOD

    # Precompute S_l for each length
    maxlen = max(d)
    S_len = [0]*(maxlen+1)
    for l in range(1, maxlen+1):
        q = [0]*(N)  # degree up to N-1
        q[0] = coeff[0]
        for k in range(1, N):
            q[k] = (coeff[k] - pow10[l]*coeff[k-1]) % MOD
        s = 0
        for k in range(N):
            s = (s + q[k]*fact[k]%MOD * fact[N-1-k])%MOD
        S_len[l] = s

    ans = 0
    for i in range(1, N+1):
        ans = (ans + i * S_len[d[i-1]])%MOD
    print(ans)

if __name__ == "__main__":
    main()
