        for i in range(0, n - lp + 1):
            if s[i:i+lp] == pref:
                pref_starts.append(i)
        suff_starts = []
        for i in range(0, n - ls + 1):
            if s[i:i+ls] == suff:
                suff_starts.append(i)
        # if pattern is just "**"
        if lp == lm == ls == 0:
            return 0
        best = None
        # if middle empty, handle separately
        if lm == 0:
            for i in pref_starts:
                # suffix start must be >= i + lp
                idx = bisect.bisect_left(suff_starts, i + lp)
                if idx < len(suff_starts):
                    k = suff_starts[idx]
                    length = (k + ls) - i
                    if best is None or length < best:
                        best = length
        else:
            mid_starts = []
            for i in range(0, n - lm + 1):
                if s[i:i+lm] == mid:
                    mid_starts.append(i)
            for j in mid_starts:
                # find i <= j - lp
                idx_i = bisect.bisect_right(pref_starts, j - lp) - 1
                if idx_i < 0:
                    continue
                i = pref_starts[idx_i]
                # find k >= j + lm
                idx_k = bisect.bisect_left(suff_starts, j + lm)
                if idx_k >= len(suff_starts):
                    continue
                k = suff_starts[idx_k]
                length = (k + ls) - i
                if best is None or length < best:
