class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        parts = p.split('*')
        prefix, mid, suffix = parts[0], parts[1], parts[2]
        lp, lm, ls = len(prefix), len(mid), len(suffix)

        # helper to find all occurrences of a pattern
        def find_occurrences(sub):
            m = len(sub)
            if m == 0:
                return list(range(n + 1))  # empty string matches at every position
            res = []
            for i in range(n - m + 1):
                if s[i:i+m] == sub:
                    res.append(i)
            return res

        pre_starts = find_occurrences(prefix)
        mid_starts = find_occurrences(mid)
        suf_starts = find_occurrences(suffix)

        # compute best prefix start with end <= pos
        best_pref_start = [None] * n
        min_start = None
        idx = 0
        for pos in range(n):
            while idx < len(pre_starts) and pre_starts[idx] + lp <= pos + 1:
                st = pre_starts[idx]
                if min_start is None or st < min_start:
                    min_start = st
                idx += 1
            best_pref_start[pos] = min_start

        # compute best suffix start with start >= pos
        best_suf_start = [None] * (n + 1)
        min_start = None
        idx = len(suf_starts) - 1
        for pos in range(n, -1, -1):
            while idx >= 0 and suf_starts[idx] >= pos:
                st = suf_starts[idx]
                if min_start is None or st < min_start:
                    min_start = st
                idx -= 1
            best_suf_start[pos] = min_start

        INF = 10**18
        ans = INF

        # handle cases where prefix or suffix may be empty
        for m_start in mid_starts:
            mid_end = m_start + lm
            pref_start = None
            if lp == 0:
                pref_start = 0
            else:
                pref_start = best_pref_start[m_start]
            if pref_start is None:
                continue
            suf_start = None
            if ls == 0:
                suf_start = mid_end
            else:
                if mid_end <= n:
                    suf_start = best_suf_start[mid_end]
            if suf_start is None:
                continue
            total_len = (suf_start + ls) - pref_start
            if total_len < ans:
                ans = total_len

        if ans == INF:
            return -1
        return ans
