class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        import bisect

        def kmp_positions(text, pat):
            if pat == "":
                return list(range(len(text)+1))
            # build lps
            lps = [0]*len(pat)
            k = 0
            for i in range(1, len(pat)):
                while k > 0 and pat[k] != pat[i]:
                    k = lps[k-1]
                if pat[k] == pat[i]:
                    k += 1
                lps[i] = k
            # search
            res = []
            k = 0
            for i, ch in enumerate(text):
                while k > 0 and pat[k] != ch:
                    k = lps[k-1]
                if pat[k] == ch:
                    k += 1
                if k == len(pat):
                    res.append(i - k + 1)
                    k = lps[k-1]
            return res

        parts = p.split('*')
        # p has exactly two '*', so parts length 3
        a, b, c = parts[0], parts[1], parts[2]
        pos_a = kmp_positions(s, a)
        pos_b = kmp_positions(s, b)
        pos_c = kmp_positions(s, c)

        if not pos_a or not pos_b or not pos_c:
            # if any required part missing, check if empty segments allow match
            # but if segment non-empty and no positions, impossible
            if (a and not pos_a) or (b and not pos_b) or (c and not pos_c):
                return -1

        min_len = None
        for start_a in pos_a:
            after_a = start_a + len(a)
            idx_b = bisect.bisect_left(pos_b, after_a)
            if idx_b == len(pos_b):
                continue
            start_b = pos_b[idx_b]
            after_b = start_b + len(b)
            idx_c = bisect.bisect_left(pos_c, after_b)
            if idx_c == len(pos_c):
                continue
            start_c = pos_c[idx_c]
            end_c = start_c + len(c)
            cur_len = end_c - start_a
            if min_len is None or cur_len < min_len:
                min_len = cur_len
        return min_len if min_len is not None else -1
