class Solution:
    def solveQueries(self, nums, queries):
        from bisect import bisect_left
        n = len(nums)
        pos = {}
        for i, v in enumerate(nums):
            pos.setdefault(v, []).append(i)
        ans_val = [-1] * n
        for indices in pos.values():
            if len(indices) < 2:
                continue
            m = len(indices)
            for idx, i in enumerate(indices):
                left = indices[idx - 1]
                right = indices[(idx + 1) % m]
                d_left = (i - left) % n
                d_right = (right - i) % n
                ans_val[i] = min(d_left, d_right)
        return [ans_val[q] for q in queries]
