class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        # function to compute minimal steps to make two letters equal
        def dist(a: str, b: str) -> int:
            d = abs(ord(a) - ord(b))
            return min(d, 26 - d)
        # dp[i][j] -> dict of cost: max length
        dp = [[dict() for _ in range(n)] for _ in range(n)]
        for i in range(n):
            dp[i][i] = {0: 1}
        for length in range(2, n + 1):
            for i in range(0, n - length + 1):
                j = i + length - 1
                d = {}
                # skip i
                for c, l in dp[i + 1][j].items():
                    if c <= k:
                        d[c] = max(d.get(c, 0), l)
                # skip j
                for c, l in dp[i][j - 1].items():
                    if c <= k:
                        d[c] = max(d.get(c, 0), l)
                # pair i and j
                cost_pair = dist(s[i], s[j])
                if cost_pair <= k:
                    for c, l in dp[i + 1][j - 1].items():
                        nc = c + cost_pair
                        if nc <= k:
                            d[nc] = max(d.get(nc, 0), l + 2)
                dp[i][j] = d
        res = 0
        for c, l in dp[0][n - 1].items():
            if c <= k and l > res:
                res = l
        return res
