class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        from functools import lru_cache

        def dist(a: str, b: str) -> int:
            d = abs(ord(a) - ord(b))
            return min(d, 26 - d)

        @lru_cache(None)
        def dfs(i: int, j: int, rem: int) -> int:
            if i > j:
                return 0
            if i == j:
                return 1
            best = max(dfs(i + 1, j, rem), dfs(i, j - 1, rem))
            d = dist(s[i], s[j])
            if d <= rem:
                best = max(best, 2 + dfs(i + 1, j - 1, rem - d))
            return best

        return dfs(0, n - 1, k)
