        for length in range(2, n+1):
            for i in range(n-length+1):
                j = i + length - 1
                if s[i] == s[j]:
                    dp[i][j] = dp[i+1][j-1] if length > 2 else 0
                else:
                    a, b = ord(s[i]), ord(s[j])
                    cost = min((a-b)%26, (b-a)%26)
                    dp[i][j] = dp[i+1][j-1] + cost
        ans = 0
        for i in range(n):
            for j in range(i, n):
                if dp[i][j] <= k:
                    ans = max(ans, j-i+1)
