class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        INF = -10**9
        # dp[i][j] is a list of length k+1, dp[i][j][c] = max length for substring i..j with cost c
        dp = [[ [INF]*(k+1) for _ in range(n) ] for _ in range(n)]
        for i in range(n):
            dp[i][i][0] = 1
        for length in range(2, n+1):
            for i in range(n-length+1):
                j = i + length - 1
                # pair cost
                a = ord(s[i]) - 97
                b = ord(s[j]) - 97
                diff = abs(a - b)
                pair_cost = min(diff, 26 - diff)
                # skip i
                for c in range(k+1):
                    dp[i][j][c] = max(dp[i][j][c], dp[i+1][j][c])
                    dp[i][j][c] = max(dp[i][j][c], dp[i][j-1][c])
                # take pair
                if pair_cost <= k:
                    for c in range(pair_cost, k+1):
                        if dp[i+1][j-1][c - pair_cost] != INF:
                            dp[i][j][c] = max(dp[i][j][c], dp[i+1][j-1][c - pair_cost] + 2)
        ans = 0
        for c in range(k+1):
            ans = max(ans, dp[0][n-1][c])
        return ans
