class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        n = len(s)
        ones = s.count('1')
        if ones == n:
            return n
        # Identify blocks
        one_sizes = []
        zero_sizes = []
        i = 0
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            size = j - i
            if s[i] == '1':
                one_sizes.append(size)
            else:
                zero_sizes.append(size)
            i = j
        zcnt = len(zero_sizes)
        if zcnt <= 1:
            return ones
        min_one = min(one_sizes)
        max_zero = max(zero_sizes)
        return min(ones + max_zero - min_one, n)
