            while j < n and t[j] == t[i]:
                j += 1
            run_len = j - i
            if t[i] == '1':
                # surrounded by zeros? check neighbors in augmented string
                if t[i-1] == '0' and t[j] == '0':
                    if min_one_len is None or run_len < min_one_len:
