            else:
                # zero run surrounded by ones
                if t[i-1] == '1' and t[j] == '1':
                    if max_zero_len is None or run_len > max_zero_len:
                        max_zero_len = run_len
            i = j
        if min_one_len is None or max_zero_len is None:
            return total_ones
        return total_ones - min_one_len + max_zero_len
