from typing import List
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        # Build index mapping for pairs
        pairs = conflictingPairs
        m = len(pairs)
        # Compute base total count
        def compute_total(rem_pair_index):
            # min_j_at_i initialization
            INF = n + 1
            min_j_at_i = [INF] * (n + 1)
            for idx, (a, b) in enumerate(pairs):
                if idx == rem_pair_index:
                    continue
                i, j = a, b
                if i > j:
                    i, j = j, i
                if j < min_j_at_i[i]:
                    min_j_at_i[i] = j
            suffix_min = [INF] * (n + 2)
            suffix_min[n + 1] = INF
            for i in range(n, 0, -1):
                suffix_min[i] = min(min_j_at_i[i], suffix_min[i + 1])
            total = 0
            for l in range(1, n + 1):
                r = suffix_min[l] - 1
                if r > n:
                    r = n
                if r >= l:
                    total += r - l + 1
            return total
        best = 0
        for idx in range(m):
            best = max(best, compute_total(idx))
        return best
