    for _ in range(n - 1):
        a = int(next(it)) - 1
        b = int(next(it)) - 1
        g[a].append(b)
        g[b].append(a)

    NEG = -10**9
    dp0 = [NEG] * n  # parent not included
    dp1 = [NEG] * n  # parent included

    parent = [-1] * n
    order = [0]
    for v in order:
        for nb in g[v]:
            if nb == parent[v]:
                continue
            parent[nb] = v
            order.append(nb)

    for v in reversed(order):
        best = [NEG] * 5  # best[k] for selecting k children
        best[0] = 0
        for nb in g[v]:
            if nb == parent[v]:
                continue
            inc = dp1[nb]
            new_best = best[:]  # skip child
            for k in range(4):
                if best[k] >= 0:
                    if k + 1 <= 4 and inc >= 0:
                        val = best[k] + inc
                        if val > new_best[k + 1]:
                            new_best[k + 1] = val
            best = new_best

        # dp0: parent not included, node degree = k
        best0 = NEG
        for k in (1, 4):
            if k <= 4 and best[k] >= 0:
                val = best[k] + 1
                if val > best0:
                    best0 = val
        dp0[v] = best0

        # dp1: parent included, node degree = k+1
        best1 = NEG
        for k in (0, 3):
            if k <= 4 and best[k] >= 0:
                val = best[k] + 1
                if val > best1:
                    best1 = val
        dp1[v] = best1

    ans = max(dp0)
    print(ans if ans >= 0 else -1)

