class Solution:
    def maxDistance(self, side: int, points: list[list[int]], k: int) -> int:
        import math
        n = len(points)
        # Precompute all pairwise Manhattan distances
        dist = [[0]*n for _ in range(n)]
        for i in range(n):
            xi, yi = points[i]
            for j in range(i+1, n):
                xj, yj = points[j]
                d = abs(xi-xj)+abs(yi-yj)
                dist[i][j] = dist[j][i] = d

        def can(d):
            # Build adjacency list of conflicts (< d)
            conflicts = [set() for _ in range(n)]
            for i in range(n):
                for j in range(i+1, n):
                    if dist[i][j] < d:
                        conflicts[i].add(j)
                        conflicts[j].add(i)

            # Recursive search for independent set of size k
            # Use simple backtracking with pruning
            order = sorted(range(n), key=lambda x: len(conflicts[x]), reverse=True)

            def dfs(start, chosen, remaining):
                if len(chosen) == k:
                    return True
                if remaining < k - len(chosen):
                    return False
                for idx in range(start, len(order)):
                    v = order[idx]
                    if any((v in conflicts[u]) for u in chosen):
                        continue
                    # choose v
                    new_remaining = remaining - 1
                    # remove its conflicts from remaining list
                    for u in conflicts[v]:
                        if u in remaining_set:
                            remaining_set.remove(u)
                            new_remaining -= 1
                    chosen.append(v)
                    if dfs(idx+1, chosen, new_remaining):
                        return True
                    chosen.pop()
                    # restore
                    for u in conflicts[v]:
                        if u not in remaining_set:
                            remaining_set.add(u)
                            new_remaining += 1
                return False

            remaining_set = set(range(n))
            return dfs(0, [], n)

        # Binary search on distance
        low, high = 0, 2*side  # maximum possible Manhattan distance on square
        while low < high:
            mid = (low + high + 1)//2
            if can(mid):
                low = mid
            else:
                high = mid-1
        return low
