class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        n = len(points)
        # precompute distances
        dist = [[0]*n for _ in range(n)]
        for i in range(n):
            xi, yi = points[i]
            for j in range(i+1, n):
                xj, yj = points[j]
                d = abs(xi-xj)+abs(yi-yj)
                dist[i][j] = dist[j][i] = d

        # adjacency bitmask for conflict (distance < d)
        def can_choose(d):
            conflict = [0]*n
            for i in range(n):
                mask = 0
                for j in range(n):
                    if i!=j and dist[i][j] < d:
                        mask |= 1<<j
                conflict[i] = mask

            # backtracking
            full = (1<<n)-1
            # order by degree
            order = list(range(n))
            order.sort(key=lambda x: bin(conflict[x]).count("1"), reverse=True)

            def dfs(idx, chosen, avail):
                if chosen==k:
                    return True
                if idx==n or chosen + (n - idx) < k:
                    return False
                v = order[idx]
                if avail & (1<<v):
                    # try pick v
                    if dfs(idx+1, chosen+1, avail & ~conflict[v] & ~(1<<v)):
                        return True
                # skip v
                return dfs(idx+1, chosen, avail & ~(1<<v))

            return dfs(0,0,full)

        lo, hi = 0, 2*side
        while lo<hi:
            mid = (lo+hi+1)//2
            if can_choose(mid):
                lo = mid
            else:
                hi = mid-1
        return lo
```

