from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        # map each point to its position along perimeter (clockwise from (0,0))
        def pos(pt):
            x, y = pt
            if y == 0:
                return x
            if x == side:
                return side + y
            if y == side:
                return 2*side + (side - x)
            # x == 0
            return 3*side + (side - y)
        N = len(points)
        L = 4*side
        arr = sorted(pos(p) for p in points)
        arr += [x + L for x in arr]  # duplicate for wrap around

        def feasible(d):
            for start in range(N):
                cnt = 1
                last = arr[start]
                idx = start + 1
                while idx < start + N and cnt < k:
                    if arr[idx] - last >= d:
                        cnt += 1
                        last = arr[idx]
                    idx += 1
                if cnt >= k:
                    return True
            return False

        lo, hi = 0, L
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo
