class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        import bisect
        L = 4 * side
        t = []
        for x, y in points:
            if x == 0:
                t.append(y)
            elif y == side:
                t.append(side + x)
            elif x == side:
                t.append(2 * side + (side - y))
            else:  # y == 0
                t.append(3 * side + (side - x))
        t.sort()
        n = len(t)
        t_ext = t + [v + L for v in t]

        def feasible(d: int) -> bool:
            for i in range(n):
                pos = t_ext[i]
                count = 1
                idx = i + 1
                limit = i + n
                while count < k:
                    target = pos + d
                    idx = bisect.bisect_left(t_ext, target, idx, limit)
                    if idx == limit:
                        break
                    pos = t_ext[idx]
                    count += 1
                if count == k:
                    return True
            return False

        lo, hi = 0, L
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo
