class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def substrings(st):
            n = len(st)
            return [st[i:j] for i in range(n+1) for j in range(i, n+1)]
        subs_s = substrings(s)
        subs_t = substrings(t)
        max_len = 0
        for a in subs_s:
            for b in subs_t:
                w = a + b
                if w == w[::-1]:
                    max_len = max(max_len, len(w))
        return max_len
