class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def is_pal(s):
            return s == s[::-1]
        n, m = len(s), len(t)
        max_len = 0
        # substrings of s
        sub_s = [s[i:j] for i in range(n) for j in range(i, n+1)]
        sub_t = [t[i:j] for i in range(m) for j in range(i, m+1)]
        for a in sub_s:
            for b in sub_t:
                if is_pal(a + b):
                    max_len = max(max_len, len(a) + len(b))
        return max_len
